_REQUIRED_FIELDS = (
    "typical_customer", "buying_process", "customer_journey", "common_integrations", "expected_kpis",
    "procurement_difficulty", "procurement_cycle", "sales_cycle", "enterprise_objections", "smb_objections",
    "pilot_strategy", "expansion_path", "expansion_triggers", "customer_acquisition_channels",
    "retention_strategy", "common_pricing_approaches", "common_failure_reasons", "common_competitive_advantages",
    "enterprise_readiness_checklist", "regulatory_considerations", "technical_stack_expectations",
    "typical_differentiation", "common_feature_roadmap",
)
for _category, _pack in _PACKS.items():
    _missing = [f for f in _REQUIRED_FIELDS if f not in _pack]
    if _missing:
        raise AssertionError(f"industry knowledge pack '{_category}' is missing required fields: {_missing}")
_missing_generic = [f for f in _REQUIRED_FIELDS if f not in _GENERIC_PACK]
if _missing_generic:
    raise AssertionError(f"generic industry knowledge pack is missing required fields: {_missing_generic}")


def get_industry_knowledge_pack(
    primary_domain: str | None,
    model_category_label: str | None,
    deployment_sectors: list[str] | None = None,
    startup_description: str | None = None,
) -> dict:
    """Returns the knowledge pack for this venture's resolved category (never a per-venture
    inference — the same deterministic category resolution every other category-flavored module
    already uses). Every field is general startup-domain knowledge, explicitly labeled as such —
    never a claim about this specific venture or a specific real company."""
    category = resolve_category(primary_domain, model_category_label, deployment_sectors, startup_description)
    pack = _PACKS.get(category, _GENERIC_PACK)
    return {
        "industry_knowledge_pack_version": INDUSTRY_KNOWLEDGE_PACK_VERSION,
        "category": category,
        **pack,
        "source": (
            f"General startup-domain knowledge for '{category}' ventures — hand-curated, "
            "qualitative patterns (no invented statistics, prices, or named companies), the same "
            "kind of category-level reference data app.agents.go_to_market_intelligence/"
            "pricing_intelligence/feature_intelligence already rely on. Never a claim about this "
            "specific venture."
        ),
    }


def supported_categories() -> list[str]:
    """All categories this knowledge base has a dedicated (non-generic) pack for — used by the
    Phase 1/7 knowledge coverage audit to report real category coverage against the full taxonomy
    app.agents.venture_vocabulary.resolve_category can produce."""
    return sorted(_PACKS.keys())
